import pandas as pd
import numpy as np

file_path = 'nasa_budget_incomplete.xlsx'

try:
    xl = pd.ExcelFile(file_path)
    print(f"Sheet names: {xl.sheet_names}")

    for sheet in xl.sheet_names:
        print(f"\n--- Sheet: {sheet} ---")
        df = xl.parse(sheet)
        print(df.head())

        # Find locations of "???"
        missing_locs = np.where(df == "???")
        if len(missing_locs[0]) > 0:
            print(f"Found '???' at:")
            for r, c in zip(*missing_locs):
                print(f"  Row {r}, Col {c} ({df.columns[c]})")
        else:
            print("No '???' found in this sheet.")

except Exception as e:
    print(f"Error: {e}")
